import {mapGetters} from "vuex";
import request from "@/router/axios";

export default {
  data() {
    return {
      form: {},
      query: {},
      loading: true,
      selectionList: [],
    }
  },
  computed: {
    ...mapGetters(["permission"]),
  },
  methods: {
    onLoad() {
      this.loading = true;
      request({
        url: '/api/idevelop-data/h3c/application/submit',
        method: 'post',
        data: {}
      }).then(res => {
        const data = res.data;
        this.page.total = data.total;
        this.data = data.records;
        this.loading = false;
        this.selectionClear();
      });
    }
  }
};
